// Shuffle helper
function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function getTopicQuestions(topicId, count = 20) {
  const bank = QUESTION_BANKS[topicId];
  if (!bank || bank.length === 0) return [];
  return shuffleArray(bank).slice(0, Math.min(count, bank.length));
}

function getMockQuestions(examKey, count) {
  // Gather all questions for this exam
  const exam = EXAMS[examKey];
  if (!exam) return [];
  let all = [];
  exam.topics.forEach(t => {
    const qs = QUESTION_BANKS[t.id] || [];
    all = all.concat(qs);
  });
  if (all.length === 0) return [];
  return shuffleArray(all).slice(0, Math.min(count, all.length));
}
